"""Command-line interface for usd-convert-cad."""

from __future__ import annotations

import argparse
import sys
from contextlib import nullcontext
from pathlib import Path

from usd_convert_cad import usdz

_SUPPORTED_OUTPUT_SUFFIXES = frozenset({".usd", ".usda", ".usdc", ".usdz"})


def _validate_output_path(output_path: Path) -> str | None:
    suffix = output_path.suffix.lower()
    if suffix not in _SUPPORTED_OUTPUT_SUFFIXES:
        supported = ", ".join(sorted(_SUPPORTED_OUTPUT_SUFFIXES))
        return f"Unsupported output extension {suffix!r}. Use one of: {supported}."
    return None


def _validate_usdz_options(args: argparse.Namespace) -> str | None:
    if args.composition_style in {"reference", "payload"}:
        return (
            "USDZ (.usdz) output requires monolithic conversion. "
            "Omit --composition-style or use --composition-style none."
        )
    return None


def _prepare_usdz_material_type(args: argparse.Namespace) -> None:
    """Prefer packageable Preview Surface materials for USDZ output.

    CAD defaults to Preview Surface already. If the user explicitly selects
    OmniPBR while exporting materials to USDZ, switch to Preview Surface and
    tell them why.
    """
    if args.no_materials:
        return
    if args.material_type != "preview-surface-omnipbr":
        return
    args.material_type = "preview-surface"
    print(
        "Note: USDZ packaging uses --material-type preview-surface "
        "(OmniPBR materials are not packageable).",
        file=sys.stderr,
    )


def _parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Convert CAD assets to USD with usd-convert-cad.")
    parser.add_argument("-i", "--input", required=True, help="Input CAD asset file path.")
    parser.add_argument(
        "-o",
        "--output",
        required=True,
        help="Output USD file path (.usd, .usda, .usdc, or .usdz).",
    )
    parser.add_argument(
        "--global-xforms", action="store_true", help="Author global transforms instead of local transforms."
    )
    parser.add_argument(
        "--convert-curves",
        action="store_true",
        help="Convert curve and wire geometry—both 3D and 2D (including DWG/DXF model-space linework)—to USD BasisCurves.",
    )
    parser.add_argument(
        "--convert-metadata", action="store_true", help="Convert CAD metadata to USD custom attributes."
    )
    parser.add_argument(
        "--read-constraints",
        action="store_true",
        help=(
            "Export CATIA V5, NX, and SolidWorks Fix constraints, plus CATIA V5 Fix Together, NX Bond, and "
            "SolidWorks Lock mates, as USD Physics fixed joints."
        ),
    )
    parser.add_argument("--no-dedup", action="store_true", help="Disable mesh and material deduplication.")
    parser.add_argument(
        "--tess-lod", type=int, choices=range(0, 5), metavar="0-4", help="Tessellation level of detail."
    )
    parser.add_argument(
        "--revit-lod",
        type=int,
        choices=range(0, 4),
        metavar="0-3",
        help="Revit detail level: 0=file default, 1=coarse, 2=medium, 3=fine.",
    )
    parser.add_argument("--accurate-tessellation", action="store_true", help="Enable accurate tessellation.")
    parser.add_argument(
        "--fast-surface-curvatures",
        action="store_true",
        help="Disable accurate surface curvature computation.",
    )
    parser.add_argument("--no-normals", action="store_true", help="Do not author normals.")
    parser.add_argument("--no-materials", action="store_true", help="Do not author materials.")
    parser.add_argument(
        "--material-type",
        choices=("none", "preview-surface", "preview-surface-omnipbr", "preview-surface-materialx"),
        help="Material output type. MaterialX authors OpenPBR with a Preview Surface fallback.",
    )
    parser.add_argument(
        "--up-axis",
        choices=("file", "y", "z"),
        help="Override output stage up-axis. Defaults to source file behavior.",
    )
    parser.add_argument(
        "--instancing-style",
        choices=("none", "reference", "instanceable-reference"),
        help="Instancing style for repeated components.",
    )
    parser.add_argument(
        "--composition-style",
        choices=("none", "reference", "payload"),
        help="Composition style for external sub-assemblies and parts.",
    )
    parser.add_argument(
        "--filter-style",
        choices=("none", "omit", "hide", "deactivate"),
        help="How hidden CAD elements are converted.",
    )
    parser.add_argument("--load-hidden", action="store_true", help="Load hidden CAD elements before filtering.")
    parser.add_argument("--progress", action="store_true", help="Print converter progress.")
    parser.add_argument("--progress-frequency", type=float, help="Progress report frequency in Hz.")
    parser.add_argument("--creator", help="Creator metadata to author on output USD layers.")
    parser.add_argument("--convert-physics-data", action="store_true", help="Author physical properties on USD prims.")
    parser.add_argument("--physics-accuracy-level", type=float, help="Physical property accuracy from 0.0 to 1.0.")
    parser.add_argument(
        "--physics-use-geometry-on-ribrep",
        action="store_true",
        help="Use geometry instead of topology for RiBRep physical properties.",
    )
    parser.add_argument("--view-layer-name", help="CAD view layer or simplified representation to convert.")
    return parser.parse_args(argv)


def _apply_args_to_params(args: argparse.Namespace, hoops: object) -> object:
    params = hoops.Parameters()
    params.globalXforms = args.global_xforms
    params.convertCurves = args.convert_curves
    params.convertMetadata = args.convert_metadata
    params.readConstraints = args.read_constraints
    params.reportProgress = args.progress
    params.dedup = not args.no_dedup
    params.accurateTessellation = args.accurate_tessellation
    params.accurateSurfaceCurvatures = not args.fast_surface_curvatures
    params.useNormals = not args.no_normals
    params.useMaterials = not args.no_materials
    params.omitHiddenOnLoad = not args.load_hidden
    params.convertPhysicsData = args.convert_physics_data
    params.physicsUseGeometryOnRiBRep = args.physics_use_geometry_on_ribrep

    if args.tess_lod is not None:
        params.tessLOD = args.tess_lod
    if args.revit_lod is not None:
        params.revitLOD = args.revit_lod
    if args.progress_frequency is not None:
        params.reportProgressFreq = args.progress_frequency
    if args.creator is not None:
        params.creator = args.creator
    if args.physics_accuracy_level is not None:
        params.physicsAccuracyLevel = args.physics_accuracy_level
    if args.view_layer_name is not None:
        params.viewLayerName = args.view_layer_name

    if args.material_type is not None:
        params.materialType = {
            "none": hoops.MaterialType.eNone,
            "preview-surface": hoops.MaterialType.ePreviewSurface,
            "preview-surface-omnipbr": hoops.MaterialType.ePreviewSurface_OmniPBR,
            "preview-surface-materialx": hoops.MaterialType.ePreviewSurface_MaterialX,
        }[args.material_type]
    if args.up_axis is not None:
        params.upAxis = {
            "file": hoops.UpAxis.eFileDefault,
            "y": hoops.UpAxis.eYup,
            "z": hoops.UpAxis.eZup,
        }[args.up_axis]
    if args.instancing_style is not None:
        params.instancingStyle = {
            "none": hoops.InstancingStyle.eNone,
            "reference": hoops.InstancingStyle.eReference,
            "instanceable-reference": hoops.InstancingStyle.eInstanceableReference,
        }[args.instancing_style]
    if args.composition_style is not None:
        params.compositionStyle = {
            "none": hoops.CompositionStyle.eNone,
            "reference": hoops.CompositionStyle.eReference,
            "payload": hoops.CompositionStyle.ePayload,
        }[args.composition_style]
    if args.filter_style is not None:
        params.filterStyle = {
            "none": hoops.FilterStyle.eNone,
            "omit": hoops.FilterStyle.eOmit,
            "hide": hoops.FilterStyle.eHide,
            "deactivate": hoops.FilterStyle.eDeactivate,
        }[args.filter_style]

    return params


def main(argv: list[str] | None = None) -> int:
    args = _parse_args(argv)
    input_path = Path(args.input).resolve()
    output_path = Path(args.output).resolve()
    is_usdz_output = usdz.is_usdz_path(output_path)

    if not input_path.is_file():
        print(f"Error: input file not found: {input_path}", file=sys.stderr)
        return 1

    output_error = _validate_output_path(output_path)
    if output_error is not None:
        print(f"Error: {output_error}", file=sys.stderr)
        return 1

    if is_usdz_output:
        usdz_error = _validate_usdz_options(args)
        if usdz_error is not None:
            print(f"Error: {usdz_error}", file=sys.stderr)
            return 1
        _prepare_usdz_material_type(args)

    output_path.parent.mkdir(parents=True, exist_ok=True)

    import omni.converter.hoops as hoops

    params = _apply_args_to_params(args, hoops)
    staging_context = usdz.temporary_staging_directory(output_path) if is_usdz_output else nullcontext(None)
    with staging_context as staging_directory:
        layer_output_path = (
            usdz.staging_layer_path(staging_directory, output_path) if is_usdz_output else output_path
        )

        error_code, error_message = hoops.convert(params, str(input_path), str(layer_output_path))
        if error_code != 0:
            print(f"Error: conversion failed with code {error_code}", file=sys.stderr)
            if error_message:
                print(error_message, file=sys.stderr)
            return 1

        if is_usdz_output:
            if not layer_output_path.is_file():
                print(
                    f"Error: conversion succeeded but staging layer was not created: {layer_output_path}",
                    file=sys.stderr,
                )
                return 1
            try:
                usdz.package_usdz(layer_output_path, output_path)
            except usdz.UsdzError as error:
                print(f"Error: {error}", file=sys.stderr)
                return 1

        print(f"Successfully converted: {output_path}")
        return 0


if __name__ == "__main__":
    raise SystemExit(main())
